"""Tests for WOT-2026-042s writer-side autogenerated rotation filtering."""

from __future__ import annotations

import ast
import json
import subprocess
import sys
from datetime import datetime, timedelta, timezone
from pathlib import Path

import pytest
import scripts.memory_consolidate as mc
from bus.portable_memory_archive import AUTOGENERATED_TOPICS


def _configure_memory_paths(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    entries: list[dict[str, object]],
) -> tuple[Path, Path]:
    """Prepare an isolated observations/archive pair for the real main path.

    Before: ``tmp_path`` is an empty pytest-owned directory and ``entries``
        are observations to consolidate.
    During: writes only the temporary observations file and redirects every
        consolidation output path used by ``main``.
    After: returns the isolated observations and archive paths.
    """
    tmp_path.mkdir(parents=True, exist_ok=True)
    obs = tmp_path / "observations.jsonl"
    obs.write_text(
        "".join(json.dumps(entry, ensure_ascii=True) + "\n" for entry in entries),
        encoding="utf-8",
    )
    archive = tmp_path / "archive"
    monkeypatch.setattr(mc, "OBS", obs)
    monkeypatch.setattr(mc, "MEMORY_DIR", tmp_path)
    monkeypatch.setattr(mc, "ARCHIVE_DIR", archive)
    monkeypatch.setattr(mc, "MEMORY_MD", tmp_path / "MEMORY.md")
    monkeypatch.setattr(mc, "MEMORY_RULES_MD", tmp_path / "memory_rules.md")
    monkeypatch.setattr(mc, "MEMORY_PROFILE_MD", tmp_path / "memory_profile.md")
    monkeypatch.setattr(mc, "REPORT", tmp_path / "CONSOLIDATION_REPORT.md")
    monkeypatch.setattr(
        mc, "TMP_REPORT", tmp_path / "runtime" / "tmp" / "CONSOLIDATION_REPORT.md"
    )
    return obs, archive


def _run_apply(monkeypatch: pytest.MonkeyPatch, since: str = "30d") -> None:
    """Run the production ``main`` apply route with an explicit cutoff.

    Before: module paths have been redirected to a temporary fixture.
    During: invokes argument parsing, pipeline recomputation, and the writer.
    After: returns after the production consolidation route completes.
    """
    monkeypatch.setattr(
        sys, "argv", ["memory_consolidate.py", "--apply", "--since", since]
    )
    mc.main()


def _topic_values_from_sources(
    sources: list[tuple[str, str]],
) -> list[tuple[str, frozenset[str]]]:
    """Extract autogenerated topic assignments from source strings.

    Before: ``sources`` contains ``(filename, Python source)`` pairs.
    During: parses each source and collects supported Assign/AnnAssign nodes
        whose target is ``AUTOGENERATED_TOPICS``.
    After: returns ``(filename, frozenset)`` pairs and raises for unsupported
        assignment forms.
    """
    assignments: list[tuple[str, frozenset[str]]] = []
    for filename, source in sources:
        tree = ast.parse(source, filename=filename)
        for node in ast.walk(tree):
            if not isinstance(node, (ast.Assign, ast.AnnAssign)):
                continue
            targets = node.targets if isinstance(node, ast.Assign) else [node.target]
            if not any(
                isinstance(target, ast.Name) and target.id == "AUTOGENERATED_TOPICS"
                for target in targets
            ):
                continue
            value = node.value
            if not (
                isinstance(value, ast.Call)
                and isinstance(value.func, ast.Name)
                and value.func.id == "frozenset"
                and len(value.args) == 1
            ):
                raise AssertionError(f"unsupported topic assignment in {filename}")
            literal = ast.literal_eval(value.args[0])
            assignments.append((filename, frozenset(literal)))
    return assignments


def _tracked_topic_references(
    repo_root: Path,
) -> tuple[list[tuple[str, frozenset[str]]], list[tuple[str, str, str]]]:
    """Collect topic assignments and imports from every tracked Python file.

    Before: ``repo_root`` is the motor repository root.
    During: anchors ``git ls-files`` to that root and parses every tracked
        Python file without a hand-maintained file list.
    After: returns assignment pairs and ``(relative path, module, alias)``
        import triples for the target identifier.
    """
    tracked = subprocess.run(
        ["git", "ls-files", "*.py"],
        cwd=repo_root,
        capture_output=True,
        text=True,
        check=True,
    ).stdout.splitlines()
    sources = [
        (relative, (repo_root / relative).read_text(encoding="utf-8"))
        for relative in tracked
    ]
    assignments = _topic_values_from_sources(sources)
    imports: list[tuple[str, str, str]] = []
    for relative, source in sources:
        tree = ast.parse(source, filename=relative)
        for node in ast.walk(tree):
            if isinstance(node, (ast.Import, ast.ImportFrom)):
                module = node.module if isinstance(node, ast.ImportFrom) else ""
                imports.extend(
                    (relative, module, alias.name)
                    for alias in node.names
                    if alias.name == "AUTOGENERATED_TOPICS"
                )
    return assignments, imports


def test_a_filtro_en_el_escritor_importa_la_constante_y_gate_ast_de_incremento(
    tmp_path: Path,
) -> None:
    """Verify the writer imports the canonical set without a new assignment.

    Before: the implementation either lacks the writer import or declares a
        second local topic set.
    During: inspects the module AST and the tracked-file assignment universe.
    After: the imported object is canonical and the only assignment is the
        allowlisted declaration in the canonical bus module.
    """
    source_path = Path("scripts/memory_consolidate.py")
    tree = ast.parse(source_path.read_text(encoding="utf-8"))
    imports = [
        node
        for node in ast.walk(tree)
        if isinstance(node, ast.ImportFrom)
        and node.module == "scripts.reconcile_portable_memory"
        and any(alias.name == "AUTOGENERATED_TOPICS" for alias in node.names)
    ]
    assert imports
    assignments, _ = _tracked_topic_references(Path(__file__).resolve().parents[2])
    allowed_topic_assignments = {
        (
            "bus/portable_memory_archive.py",
            frozenset({"architecture", "ticket-completion"}),
        ),
    }
    collected = set(assignments)
    assert collected, "el scanner AST no encontro la declaracion canonica"
    assert collected <= allowed_topic_assignments, (
        "INCREMENTO de AUTOGENERATED_TOPICS fuera de la allowlist: "
        f"{sorted(collected - allowed_topic_assignments)}"
    )
    assert mc.AUTOGENERATED_TOPICS is AUTOGENERATED_TOPICS


def test_b_telemetria_autogenerada_no_rota_al_archive(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    """Keep non-noise autogenerated telemetry in live observations.

    Before: the old writer archives every age-split entry.
    During: runs the real ``main --apply`` route with a 31-day architecture
        entry whose signal bypasses both noise predicates.
    After: no archive contains the telemetry and observations.jsonl retains it.
    """
    entry = {
        "topic": "architecture",
        "signal": "Decisiones arquitectonicas documentadas en PROJECT.md durante el cierre",
        "timestamp": (datetime.now(timezone.utc) - timedelta(days=31)).isoformat(),
        "source_ticket": "WOT-2026-042s",
    }
    assert entry["topic"] in mc.AUTOGENERATED_TOPICS
    assert mc.is_noise(entry["signal"]) is False
    assert mc.is_droppable_noise(entry) is False
    obs, archive = _configure_memory_paths(tmp_path, monkeypatch, [entry])

    _run_apply(monkeypatch)

    archived = [
        item
        for path in archive.glob("observations.*.jsonl")
        for item in mc.parse_entries(path)
        if item.get("topic") == "architecture"
    ]
    assert archived == []
    assert obs.exists()
    live = mc.parse_entries(obs)
    assert live and live[0]["topic"] == "architecture"


def test_d_leccion_legitima_sigue_rotando(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    """Keep the legitimate lesson rotation anti-false-positive.

    Before: an overbroad filter could stop all old observations from rotating.
    During: runs the same production writer path with a non-autogenerated topic.
    After: the lesson is in the current archive and absent from observations.
    """
    entry = {
        "topic": "lecciones",
        "signal": "Una leccion legitima debe seguir rotando al archive sin telemetria",
        "timestamp": (datetime.now(timezone.utc) - timedelta(days=31)).isoformat(),
        "source_ticket": "WOT-2026-042s",
    }
    assert entry["topic"] not in mc.AUTOGENERATED_TOPICS
    obs, archive = _configure_memory_paths(tmp_path, monkeypatch, [entry])

    _run_apply(monkeypatch)

    archived = [
        item
        for path in archive.glob("observations.*.jsonl")
        for item in mc.parse_entries(path)
    ]
    assert any(item.get("topic") == "lecciones" for item in archived)
    assert mc.parse_entries(obs) == []


def test_e_scanner_ast_no_divergencia_sobre_tracked_py(tmp_path: Path) -> None:
    """Check equality of all tracked assignments and divergent synthetic files.

    Before: divergent canonical copies could silently define different topics.
    During: scans the motor tracked universe and separately exercises the value
        detector with two temporary divergent Python files.
    After: tracked values equal the bus canonical set and synthetic divergence
        is detected without enumerating production files manually.
    """
    repo_root = Path(__file__).resolve().parents[2]
    assignments, imports = _tracked_topic_references(repo_root)
    values = {value for _, value in assignments}
    assert values == {frozenset(AUTOGENERATED_TOPICS)}
    assert imports
    allowed_import_modules = {
        "bus.portable_memory_archive",
        "scripts.reconcile_portable_memory",
    }
    assert all(module in allowed_import_modules for _, module, _ in imports)
    imported_paths = {relative for relative, _, _ in imports}
    assigned_paths = {relative for relative, _ in assignments}
    assert "scripts/memory_consolidate.py" in imported_paths
    assert "scripts/memory_consolidate.py" not in assigned_paths

    synthetic = _topic_values_from_sources(
        [
            ("first.py", "AUTOGENERATED_TOPICS = frozenset({'architecture'})\n"),
            (
                "second.py",
                "AUTOGENERATED_TOPICS = frozenset({'ticket-completion'})\n",
            ),
        ]
    )
    assert len({value for _, value in synthetic}) == 2


def test_g_since_controla_el_cutoff_del_escritor(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    """Verify the explicit since cutoff controls the writer in both directions.

    Before: a writer-side hardcoded cutoff ignores the requested suffix.
    During: runs identical ten-day lessons in isolated 5-day and 40-day cases.
    After: the first archives and the second retains the lesson live.
    """
    entry = {
        "topic": "lecciones",
        "signal": "Una leccion de diez dias prueba que since gobierna la rotacion",
        "timestamp": (datetime.now(timezone.utc) - timedelta(days=10)).isoformat(),
        "source_ticket": "WOT-2026-042s",
    }
    first_obs, first_archive = _configure_memory_paths(
        tmp_path / "five", monkeypatch, [entry]
    )
    _run_apply(monkeypatch, "5d")
    assert any(first_archive.glob("observations.*.jsonl"))
    assert mc.parse_entries(first_obs) == []

    second_obs, second_archive = _configure_memory_paths(
        tmp_path / "forty", monkeypatch, [entry]
    )
    _run_apply(monkeypatch, "40d")
    assert not list(second_archive.glob("observations.*.jsonl"))
    assert mc.parse_entries(second_obs) == [entry]
